#include <string>
using namespace std;

class Solution {
public:
    bool checkRecord(string s) {
        int aCount = 0, lStreak = 0;
        for (char c : s) {
            if (c == 'A') {
                aCount++;
                if (aCount > 1) return false;
                lStreak = 0;
            } else if (c == 'L') {
                lStreak++;
                if (lStreak > 2) return false;
            } else {
                lStreak = 0;
            }
        }
        return true;
    }
};
